const METRICS = {
    totalCustomers: 70,
    newCustomers: 70,
    weeklyChange: -8
};

export default function CustomersPage() {
    const [search, setSearch] = useState("");
    const [selectedCustomer, setSelectedCustomer] = useState<string | null>(null);
    const [filterStatus, setFilterStatus] = useState("All");
    const [filterCategory, setFilterCategory] = useState("Electronics");

    const filteredCustomers = STATIC_CUSTOMERS.filter(customer => {
        const matchesSearch = customer.customerName.toLowerCase().includes(search.toLowerCase()) ||
                            customer.email.toLowerCase().includes(search.toLowerCase()) ||
                            customer.companyName.toLowerCase().includes(search.toLowerCase());
        const matchesStatus = filterStatus === "All" || customer.status === filterStatus;
        return matchesSearch && matchesStatus;
    });

    const formatCurrency = (val: number) => {
        return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(val);
    };

    const getStatusColor = (status: string) => {
        switch (status) {
            case "VIP": return "bg-emerald-100 text-emerald-700 border-emerald-200";
            case "Returning": return "bg-blue-100 text-blue-700 border-blue-200";
            case "New": return "bg-slate-100 text-slate-700 border-slate-200";
            default: return "bg-gray-100 text-gray-700 border-gray-200";
        }
    };

    return (
        <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 p-6">
            <div className="max-w-[1600px] mx-auto">
                {/* Header */}
                <header className="mb-8">
                    <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
                        <h1 className="text-4xl font-bold text-slate-800">Customers Overview</h1>
                        
                        <div className="flex items-center gap-3 w-full md:w-auto">
                            <div className="relative flex-1 md:flex-none md:w-80">
                                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
                                <Input
                                    placeholder="Search here..."
                                    value={search}
                                    onChange={(e) => setSearch(e.target.value)}
                                    className="pl-12 h-12 rounded-xl border-slate-200 bg-white shadow-sm"
                                />
                            </div>
                            <Button className="bg-[#5b4da3] hover:bg-[#4a3d82] text-white px-6 h-12 rounded-xl shadow-sm">
                                <Plus size={20} className="mr-2" />
                                Add Customer
                            </Button>
                        </div>
                    </div>
                </header>

                {/* Metrics Cards */}
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
                    {/* Total Customers */}
                    <Card className="bg-white border-0 shadow-md rounded-2xl overflow-hidden">
                        <CardContent className="p-6">
                            <div className="flex items-start justify-between mb-4">
                                <div>
                                    <p className="text-slate-500 text-sm font-medium mb-1">Total Customer</p>
                                    <div className="flex items-center gap-2">
                                        <p className="text-4xl font-bold text-slate-800">{METRICS.totalCustomers}</p>
                                        <select className="text-xs text-slate-500 border border-slate-200 rounded-lg px-2 py-1">
                                            <option>Weekly</option>
                                            <option>Monthly</option>
                                        </select>
                                    </div>
                                </div>
                                <div className="bg-amber-100 p-3 rounded-xl">
                                    <User className="text-amber-600" size={24} />
                                </div>
                            </div>
                            <div className="flex items-center gap-1 text-xs">
                                <span className="text-red-500 font-medium">↓ 8%</span>
                                <span className="text-slate-500">vs Last Week</span>
                            </div>
                        </CardContent>
                    </Card>

                    {/* New Customers */}
                    <Card className="bg-white border-0 shadow-md rounded-2xl overflow-hidden">
                        <CardContent className="p-6">
                            <div className="flex items-start justify-between mb-4">
                                <div>
                                    <p className="text-slate-500 text-sm font-medium mb-1">New Customer</p>
                                    <div className="flex items-center gap-2">
                                        <p className="text-4xl font-bold text-slate-800">{METRICS.newCustomers}</p>
                                        <select className="text-xs text-slate-500 border border-slate-200 rounded-lg px-2 py-1">
                                            <option>Weekly</option>
                                            <option>Monthly</option>
                                        </select>
                                    </div>
                                </div>
                                <div className="bg-emerald-100 p-3 rounded-xl">
                                    <User className="text-emerald-600" size={24} />
                                </div>
                            </div>
                            <div className="flex items-center gap-1 text-xs">
                                <span className="text-red-500 font-medium">↓ 8%</span>
                                <span className="text-slate-500">vs Last Week</span>
                            </div>
                        </CardContent>
                    </Card>

                    {/* Top Customers */}
                    <Card className="bg-white border-0 shadow-md rounded-2xl overflow-hidden">
                        <CardContent className="p-6">
                            <p className="text-slate-800 font-semibold mb-4">Top 10 Customers this Week!</p>
                            <div className="space-y-3">
                                {STATIC_CUSTOMERS.slice(0, 2).map((customer) => (
                                    <div key={customer.id} className="flex items-center gap-3">
                                        <img src={customer.companyLogo} alt={customer.customerName} className="w-10 h-10 rounded-full" />
                                        <div className="flex-1">
                                            <p className="font-semibold text-slate-800 text-sm">{customer.customerName}</p>
                                            <p className="text-xs text-slate-500">Spent: {formatCurrency(customer.totalSpent)}</p>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </CardContent>
                    </Card>
                </div>

                {/* Main Table Card */}
                <Card className="bg-white border-0 shadow-md rounded-2xl overflow-hidden">
                    <CardContent className="p-0">
                        {/* Table Header with Filters */}
                        <div className="flex items-center justify-between px-6 py-5 border-b border-slate-100">
                            <h2 className="text-xl font-bold text-slate-800">Customers List</h2>
                            
                            <div className="flex gap-3">
                                <select 
                                    value={filterCategory} 
                                    onChange={(e) => setFilterCategory(e.target.value)}
                                    className="border border-slate-200 bg-white text-slate-700 rounded-lg px-4 py-2 text-sm font-medium"
                                >
                                    <option>Electronics</option>
                                    <option>Software</option>
                                    <option>Services</option>
                                </select>
                                
                                <select 
                                    value={filterStatus} 
                                    onChange={(e) => setFilterStatus(e.target.value)}
                                    className="border border-slate-200 bg-white text-slate-700 rounded-lg px-4 py-2 text-sm font-medium"
                                >
                                    <option>All</option>
                                    <option>VIP</option>
                                    <option>Returning</option>
                                    <option>New</option>
                                </select>
                            </div>
                        </div>

                        {/* Table */}
                        <div className="overflow-x-auto">
                            <Table>
                                <TableHeader className="bg-slate-50/80">
                                    <TableRow>
                                        <TableHead className="font-semibold text-slate-600">Company</TableHead>
                                        <TableHead className="font-semibold text-slate-600">Customer</TableHead>
                                        <TableHead className="font-semibold text-slate-600">Email</TableHead>
                                        <TableHead className="font-semibold text-slate-600">Plan</TableHead>
                                        <TableHead className="font-semibold text-slate-600">Plan Type</TableHead>
                                        <TableHead className="font-semibold text-slate-600">Start Date</TableHead>
                                        <TableHead className="font-semibold text-slate-600">End Date</TableHead>
                                        <TableHead className="font-semibold text-slate-600">Status</TableHead>
                                        <TableHead className="font-semibold text-slate-600">Action</TableHead>
                                    </TableRow>
                                </TableHeader>
                                <TableBody>
                                    {filteredCustomers.map((customer) => (
                                        <>
                                            <TableRow 
                                                key={customer.id} 
                                                className="hover:bg-slate-50/50 transition-colors cursor-pointer border-b border-slate-100"
                                                onClick={() => setSelectedCustomer(selectedCustomer === customer.id ? null : customer.id)}
                                            >
                                                {/* Company Logo & Name */}
                                                <TableCell>
                                                    <div className="flex items-center gap-3">
                                                        <img 
                                                            src={customer.companyLogo} 
                                                            alt={customer.companyName} 
                                                            className="w-10 h-10 rounded-full object-cover"
                                                        />
                                                        <div>
                                                            <p className="font-semibold text-slate-800">{customer.companyName}</p>
                                                            <p className="text-xs text-slate-500">ID: {customer.id}</p>
                                                        </div>
                                                    </div>
                                                </TableCell>

                                                {/* Customer Name & Role */}
                                                <TableCell>
                                                    <div>
                                                        <p className="font-semibold text-slate-800">{customer.customerName}</p>
                                                        <p className="text-xs text-slate-500">{customer.customerRole}</p>
                                                    </div>
                                                </TableCell>

                                                {/* Email */}
                                                <TableCell>
                                                    <span className="text-slate-600 text-sm">{customer.email}</span>
                                                </TableCell>

                                                {/* Plan Details */}
                                                <TableCell>
                                                    <Badge className="bg-purple-100 text-purple-700 border-purple-200 font-medium">
                                                        {customer.plan}
                                                    </Badge>
                                                </TableCell>

                                                {/* Plan Type (Monthly/Yearly) */}
                                                <TableCell>
                                                    <Badge className={`${customer.planType === 'yearly' ? 'bg-emerald-100 text-emerald-700 border-emerald-200' : 'bg-blue-100 text-blue-700 border-blue-200'} font-medium capitalize`}>
                                                        {customer.planType}
                                                    </Badge>
                                                </TableCell>

                                                {/* Plan Start Date */}
                                                <TableCell>
                                                    <span className="text-slate-600 text-sm font-medium">{customer.planStartDate}</span>
                                                </TableCell>

                                                {/* Plan End Date */}
                                                <TableCell>
                                                    <span className="text-slate-600 text-sm font-medium">{customer.planEndDate}</span>
                                                </TableCell>

                                                {/* Status */}
                                                <TableCell>
                                                    <Badge className={`${getStatusColor(customer.status)} border font-medium px-3 py-1`}>
                                                        {customer.status}
                                                    </Badge>
                                                </TableCell>

                                                {/* Action */}
                                                <TableCell>
                                                    <Button variant="ghost" size="sm" className="hover:bg-slate-100">
                                                        <MoreHorizontal size={18} className="text-slate-400" />
                                                    </Button>
                                                </TableCell>
                                            </TableRow>

                                            {/* Expanded Details Row */}
                                            {selectedCustomer === customer.id && (
                                                <TableRow className="bg-slate-50/50">
                                                    <TableCell colSpan={6} className="p-6">
                                                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                                                            {/* Company Details */}
                                                            <div className="bg-white p-5 rounded-xl border border-slate-200">
                                                                <div className="flex items-center gap-2 mb-4">
                                                                    <Building2 className="text-[#5b4da3]" size={20} />
                                                                    <h3 className="font-bold text-slate-800">Company Details</h3>
                                                                </div>
                                                                <div className="space-y-2 text-sm">
                                                                    <div className="flex justify-between">
                                                                        <span className="text-slate-500">Company Name:</span>
                                                                        <span className="font-semibold text-slate-800">{customer.companyName}</span>
                                                                    </div>
                                                                    <div className="flex justify-between">
                                                                        <span className="text-slate-500">Customer Role:</span>
                                                                        <span className="font-semibold text-slate-800">{customer.customerRole}</span>
                                                                    </div>
                                                                    <div className="flex justify-between">
                                                                        <span className="text-slate-500">Phone:</span>
                                                                        <span className="font-semibold text-slate-800">{customer.phone}</span>
                                                                    </div>
                                                                </div>
                                                            </div>

                                                            {/* Plan Details */}
                                                            <div className="bg-white p-5 rounded-xl border border-slate-200">
                                                                <div className="flex items-center gap-2 mb-4">
                                                                    <CreditCard className="text-emerald-600" size={20} />
                                                                    <h3 className="font-bold text-slate-800">Plan Details</h3>
                                                                </div>
                                                                <div className="space-y-2 text-sm">
                                                                    <div className="flex justify-between">
                                                                        <span className="text-slate-500">Plan:</span>
                                                                        <span className="font-semibold text-slate-800">{customer.plan}</span>
                                                                    </div>
                                                                    <div className="flex justify-between">
                                                                        <span className="text-slate-500">Billing:</span>
                                                                        <Badge className="bg-blue-100 text-blue-700 border-blue-200">
                                                                            {customer.planType}
                                                                        </Badge>
                                                                    </div>
                                                                    <div className="flex justify-between">
                                                                        <span className="text-slate-500">Start Date:</span>
                                                                        <span className="font-semibold text-slate-800">{customer.planStartDate}</span>
                                                                    </div>
                                                                    <div className="flex justify-between">
                                                                        <span className="text-slate-500">End Date:</span>
                                                                        <span className="font-semibold text-slate-800">{customer.planEndDate}</span>
                                                                    </div>
                                                                    <div className="flex justify-between items-center">
                                                                        <span className="text-slate-500">Activated:</span>
                                                                        <Badge className={customer.isActivated ? "bg-emerald-100 text-emerald-700 border-emerald-200" : "bg-red-100 text-red-700 border-red-200"}>
                                                                            {customer.isActivated ? "Yes" : "No"}
                                                                        </Badge>
                                                                    </div>
                                                                </div>
                                                            </div>

                                                            {/* Payment Details */}
                                                            <div className="bg-white p-5 rounded-xl border border-slate-200">
                                                                <div className="flex items-center gap-2 mb-4">
                                                                    <FileText className="text-amber-600" size={20} />
                                                                    <h3 className="font-bold text-slate-800">Payment Details</h3>
                                                                </div>
                                                                <div className="space-y-2 text-sm">
                                                                    <div className="flex justify-between items-center">
                                                                        <span className="text-slate-500">Status:</span>
                                                                        <Badge className={customer.paymentStatus === "paid" ? "bg-emerald-100 text-emerald-700 border-emerald-200" : "bg-amber-100 text-amber-700 border-amber-200"}>
                                                                            {customer.paymentStatus}
                                                                        </Badge>
                                                                    </div>
                                                                    <div className="flex justify-between items-center">
                                                                        <span className="text-slate-500">Invoice:</span>
                                                                        <Button size="sm" variant="outline" className="h-7 text-xs border-slate-300">
                                                                            <Download size={14} className="mr-1" />
                                                                            Download
                                                                        </Button>
                                                                    </div>
                                                                </div>
                                                            </div>

                                                            {/* VPS Credentials */}
                                                            <div className="bg-white p-5 rounded-xl border border-slate-200">
                                                                <div className="flex items-center gap-2 mb-4">
                                                                    <Server className="text-blue-600" size={20} />
                                                                    <h3 className="font-bold text-slate-800">VPS Credentials</h3>
                                                                </div>
                                                                <div className="space-y-2 text-sm">
                                                                    <div>
                                                                        <span className="text-slate-500 block mb-1">Host:</span>
                                                                        <code className="bg-slate-100 px-2 py-1 rounded text-xs font-mono block">{customer.vpsCredentials.host}</code>
                                                                    </div>
                                                                    <div>
                                                                        <span className="text-slate-500 block mb-1">Username:</span>
                                                                        <code className="bg-slate-100 px-2 py-1 rounded text-xs font-mono block">{customer.vpsCredentials.username}</code>
                                                                    </div>
                                                                    <div>
                                                                        <span className="text-slate-500 block mb-1">Password:</span>
                                                                        <code className="bg-slate-100 px-2 py-1 rounded text-xs font-mono block">{customer.vpsCredentials.password}</code>
                                                                    </div>
                                                                </div>
                                                            </div>

                                                            {/* Admin Credentials */}
                                                            <div className="bg-white p-5 rounded-xl border border-slate-200">
                                                                <div className="flex items-center gap-2 mb-4">
                                                                    <Shield className="text-purple-600" size={20} />
                                                                    <h3 className="font-bold text-slate-800">Admin Credentials</h3>
                                                                </div>
                                                                <div className="space-y-2 text-sm">
                                                                    <div>
                                                                        <span className="text-slate-500 block mb-1">Username:</span>
                                                                        <code className="bg-slate-100 px-2 py-1 rounded text-xs font-mono block">{customer.adminCredentials.username}</code>
                                                                    </div>
                                                                    <div>
                                                                        <span className="text-slate-500 block mb-1">Password:</span>
                                                                        <code className="bg-slate-100 px-2 py-1 rounded text-xs font-mono block">{customer.adminCredentials.password}</code>
                                                                    </div>
                                                                </div>
                                                            </div>
                                                        </div>
                                                    </TableCell>
                                                </TableRow>
                                            )}
                                        </>
                                    ))}
                                </TableBody>
                            </Table>
                        </div>
                    </CardContent>
                </Card>
            </div>
        </div>
    );
}